COMMENT ON COLUMN treasury_fx_deal_leg.custom_field_2 IS 'Tenant-defined custom field 2; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN treasury_fx_deal_leg.custom_field_3 IS 'Tenant-defined custom field 3; label, type and validation configured in custom_field_definition';
